const r2 = v => Math.round(v * 100) / 100;
const FAMILY = 'water-expansion';
const INSPECTED = '2026-11-18';

// ---- shared bottle machinery -------------------------------------------------------------
// pts: right half [[y, halfWidth], ...] from the top of the neck finish down to the base.
function outline(pts, foot = 0) {
  const P = pts.map(([y, h]) => [100 + h, y]);
  const seg = (A, rev) => {
    let s = '';
    for (let i = 0; i < A.length - 1; i++) {
      const p0 = A[Math.max(i - 1, 0)], p1 = A[i], p2 = A[i + 1], p3 = A[Math.min(i + 2, A.length - 1)];
      const len = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]) / 3;
      const lim = (dx, dy) => { const l = Math.hypot(dx, dy) || 1, f = Math.min(1, len / l); return [dx * f, dy * f]; };
      const t1 = lim((p2[0] - p0[0]) / 6, (p2[1] - p0[1]) / 6), t2 = lim((p3[0] - p1[0]) / 6, (p3[1] - p1[1]) / 6);
      const c1 = [p1[0] + t1[0], p1[1] + t1[1]];
      const c2 = [p2[0] - t2[0], p2[1] - t2[1]];
      s += `C${r2(c1[0])} ${r2(c1[1])} ${r2(c2[0])} ${r2(c2[1])} ${r2(p2[0])} ${r2(p2[1])}`;
    }
    return s;
  };
  const L = P.map(([x, y]) => [200 - x, y]).reverse();
  const last = P[P.length - 1];
  let bottom = `L${r2(200 - last[0])} ${r2(last[1])}`;
  if (foot) { // petaloid feet seen from the front: shallow arches between feet
    const n = 4, x0 = last[0], x1 = 200 - last[0];
    bottom = '';
    for (let i = 1; i <= n; i++) {
      const xa = x0 + (x1 - x0) * (i - 1) / n, xb = x0 + (x1 - x0) * i / n, xm = (xa + xb) / 2;
      bottom += `Q${r2(xm)} ${r2(last[1] - foot)} ${r2(xb)} ${r2(last[1])}`;
    }
  }
  return `M${r2(P[0][0])} ${r2(P[0][1])}${seg(P)}${bottom}${seg(L)}Z`;
}
