// ---- Deer Park 16.9 fl oz -----------------------------------------------------------------
const DP_PTS = [[34, 13.3], [39.6, 13.3], [41.9, 15.7], [44, 17.7], [48, 21], [52, 24.2], [56, 27], [61.4, 29.4], [66.8, 32.3], [72.3, 34.3], [77.7, 34.8], [84, 34.2], [90, 33.9], [127, 33.1], [132, 32.7], [137.4, 31.5], [142.8, 29.4], [148.2, 27.4], [153.6, 26.2], [159, 26.6], [164.5, 27.8], [169.9, 28.4], [180.8, 30], [191.6, 30.6], [202.5, 30.2], [213.3, 29.8], [218.7, 28.2], [224.2, 26.2], [229.6, 22.2], [234, 15]];
function deerPark() {
  const k = 'dp', d = outline(DP_PTS, 2.4);
  const defs = glassDefs(k) + clipDef(k, d) + capShadeDef +
    `<linearGradient id="__ID__dpSky" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#0a3684"/><stop offset=".35" stop-color="#1c4f9a"/><stop offset=".6" stop-color="#565a88"/><stop offset=".78" stop-color="#8c6466"/><stop offset="1" stop-color="#1c1736"/></linearGradient>` +
    `<radialGradient id="__ID__dpGlow" cx="127" cy="104" r="13" gradientUnits="userSpaceOnUse"><stop stop-color="#ffd526"/><stop offset=".45" stop-color="#f6c11c"/><stop offset=".8" stop-color="#d9935a" stop-opacity=".7"/><stop offset="1" stop-color="#9a7579" stop-opacity="0"/></radialGradient>`;
  // shoulder: five pointed arch panels (outer ones foreshortened)
  let arches = '';
  for (const t of [-.78, -.4, 0, .4, .78]) {
    const cx = 100 + t * 30, w = r2(4.6 * Math.sqrt(1 - t * t)), top = r2(50 + Math.abs(t) * 9);
    arches += mold(`M${r2(cx - w)} 88V${r2(top + 9)}Q${r2(cx - w)} ${r2(top + 3)} ${r2(cx)} ${top}Q${r2(cx + w)} ${r2(top + 3)} ${r2(cx + w)} ${r2(top + 9)}V88`, .9, .4);
  }
  // waist: an inverted V, then four scalloped grip rings and vertical facet lines
  let grip = mold('M68 151L100 141.5L132 151', 1.1, .5) + mold('M69 155L100 146L131 155', .7, .3);
  for (const y of [162, 173, 184, 195, 206]) {
    grip += mold(`M70 ${y}Q78 ${y + 3} 86 ${y + 1.5}Q93 ${y + 3.4} 100 ${y + 2}Q107 ${y + 3.4} 114 ${y + 1.5}Q122 ${y + 3} 130 ${y}`, 1.1, .5);
  }
  for (const x of [84, 116]) grip += `<path d="M${x} 164V213" stroke="#fff" stroke-opacity=".35" stroke-width=".8"/>`;
  const base = mold('M74 226Q82 231 87 226M93 227Q100 232 107 227M113 226Q118 231 126 226', .9, .5);
  const label = `<g clip-path="${ref('dpClip')}">` +
    `<rect x="60" y="89.8" width="80" height="37.6" fill="${ref('dpSky')}"/>` +
    `<rect x="60" y="89.8" width="80" height="37.6" fill="${ref('dpGlow')}"/>` +
    `<path d="${DP_FIELD}" fill="#1a1a3c" fill-rule="evenodd"/><path d="${DP_ELK}" fill="#17183a" fill-rule="evenodd"/>` +
    `<rect x="60" y="89.8" width="80" height="2.9" fill="#000c40"/><rect x="60" y="124.1" width="80" height="3.3" fill="#000022"/>` +
    `<path d="${DP_MARK}" fill="#fff" fill-rule="evenodd" stroke="#0c1546" stroke-width=".35" stroke-opacity=".7"/>` +
    `<path d="${DP_TXT_L}" fill="#fff" fill-opacity=".85" fill-rule="evenodd"/><path d="${DP_TXT_R}" fill="#fff" fill-opacity=".85" fill-rule="evenodd"/></g>`;
  const body = shadow(36) + bottle(k, d, 44, 20.5) + arches + grip + base + label + shadeBand(k, 89.8, 37.6) +
    gloss(k, 70, 222, 34) + ring(31.6, 15.7, 2.6, '#f2f2f0', '#b7b9bb') + cap(18, 31.8, 14.6, '#f6f6f4', '#a9abad', '#ffffff', 16, 2.2);
  return {body, defs};
}

